using System;using System.Collections.Generic;namespace Mapping{    /// <summary>    ///     /// </summary>    public class TransferMap    {        /// <summary>        ///         /// </summary>        /// <param name="fromSubstrateId"></param>        /// <param name="toSubstrateId"></param>        public TransferMap(string fromSubstrateId, string toSubstrateId)        {            this.FromSubstrateId = fromSubstrateId;            this.ToSubstrateId = toSubstrateId;            this.FromUnits = new List<Unit>();            this.ToUnits = new List<Unit>();        }        /// <summary>        ///         /// </summary>        public string FromSubstrateId { get; }        /// <summary>        ///         /// </summary>        public string ToSubstrateId { get; }        /// <summary>        ///         /// </summary>        public List<Unit> FromUnits { get; }        /// <summary>        ///         /// </summary>        public List<Unit> ToUnits { get; }    }}